template:
# 1. Upload the whole local posters folder, including subfolders
aws s3 {{0}} ./posters/ s3://lantern-posters/posters/ --{{1}}

# 2. Keep old versions when posters are overwritten or deleted
aws s3api put-bucket-versioning --bucket lantern-posters \
  --versioning-configuration Status={{2}}

# 3. Store this month's export in the cheapest archive class
aws s3 cp ./exports/2026-09.sql.gz s3://lantern-backups/exports/ \
  --storage-class {{3}}
